CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_FUEL_COST_MONTH_TYPE_ACCOUNT_CODE
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_FUEL_COST at grain Date.FiscalYear, Date.MonthName, Date.Quarter, FuelCost.FuelType, GLAccount.AccountCode, Date.MonthNumber; covers 44.52% of weighted demand (2 clusters); est. 6,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       d1.QUARTER,
       f.FUEL_TYPE,
       g2.ACCOUNT_CODE,
       d1.MONTH_NUMBER,
       SUM(f.COST_PER_MMBTU) AS COST_PER_MMBTU_SUM,
       COUNT(f.COST_PER_MMBTU) AS COST_PER_MMBTU_COUNT,
       SUM(f.QUANTITY_MMBTU) AS QUANTITY_MMBTU,
       SUM(f.TOTAL_COST) AS TOTAL_COST,
       COUNT(*) AS FUEL_COST_COUNT
FROM CORE.FCT_FUEL_COST f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_GL_ACCOUNT g2 ON f.GL_ACCOUNT_ID = g2.GL_ACCOUNT_ID
GROUP BY ALL;

